"""Dependency-free tests for login.py (run with: python test_login.py).

Each test uses an in-memory database so the real user_credentials.db is never
touched.
"""

import hashlib
import sqlite3

import login


def make_conn() -> sqlite3.Connection:
    return login.connect(":memory:")


def test_register_and_login():
    conn = make_conn()
    login.register_user(conn, "alice", "alice@example.com", "correct horse")
    row = login.login_user(conn, "alice", "correct horse")
    assert row is not None
    assert row["email"] == "alice@example.com"


def test_login_by_email():
    conn = make_conn()
    login.register_user(conn, "bob", "bob@example.com", "battery staple")
    row = login.login_user(conn, "bob@example.com", "battery staple")
    assert row is not None
    assert row["username"] == "bob"


def test_wrong_password_rejected():
    conn = make_conn()
    login.register_user(conn, "carol", "carol@example.com", "secret123")
    assert login.login_user(conn, "carol", "wrongpass") is None


def test_unknown_user_rejected():
    conn = make_conn()
    assert login.login_user(conn, "nobody", "anything") is None


def test_duplicate_email_rejected():
    conn = make_conn()
    login.register_user(conn, "dave", "dave@example.com", "password1")
    try:
        login.register_user(conn, "dave2", "dave@example.com", "password2")
    except ValueError:
        pass
    else:
        raise AssertionError("duplicate email should have raised ValueError")


def test_duplicate_username_rejected():
    conn = make_conn()
    login.register_user(conn, "erin", "erin@example.com", "password1")
    try:
        login.register_user(conn, "erin", "other@example.com", "password2")
    except ValueError:
        pass
    else:
        raise AssertionError("duplicate username should have raised ValueError")


def test_short_password_rejected():
    conn = make_conn()
    try:
        login.register_user(conn, "frank", "frank@example.com", "short")
    except ValueError:
        pass
    else:
        raise AssertionError("short password should have raised ValueError")


def test_invalid_email_rejected():
    conn = make_conn()
    try:
        login.register_user(conn, "grace", "not-an-email", "password1")
    except ValueError:
        pass
    else:
        raise AssertionError("invalid email should have raised ValueError")


def test_legacy_sha256_hash_still_works():
    """Existing DB rows use unsalted SHA-256; those users must still log in."""
    conn = make_conn()
    legacy_hash = hashlib.sha256(b"oldpassword").hexdigest()
    conn.execute(
        "INSERT INTO users (username, email, password_hash, created_date) "
        "VALUES (?, ?, ?, ?)",
        ("legacy", "legacy@example.com", legacy_hash, "2024-01-01"),
    )
    conn.commit()
    assert login.login_user(conn, "legacy", "oldpassword") is not None
    assert login.login_user(conn, "legacy", "wrong") is None


def test_new_hash_is_salted():
    """Two users with the same password must not share a stored hash."""
    conn = make_conn()
    login.register_user(conn, "henry", "henry@example.com", "samepass1")
    login.register_user(conn, "irene", "irene@example.com", "samepass1")
    h1 = conn.execute(
        "SELECT password_hash FROM users WHERE username = ?", ("henry",)
    ).fetchone()[0]
    h2 = conn.execute(
        "SELECT password_hash FROM users WHERE username = ?", ("irene",)
    ).fetchone()[0]
    assert h1 != h2
    assert h1.startswith("pbkdf2_sha256$")


if __name__ == "__main__":
    tests = [
        (name, fn)
        for name, fn in sorted(globals().items())
        if name.startswith("test_") and callable(fn)
    ]
    for name, fn in tests:
        fn()
        print(f"PASS {name}")
    print(f"\nAll {len(tests)} tests passed.")
